raw = [json.loads(l) for l in open('01-decisions/output/decisions-raw.jsonl')]
id2can = {c['id']: c for c in can}
replaces_map = {}
replaced_by_map = {}
for c in can:
    for rid in (c.get('replaces') or []):
        replaces_map.setdefault(c['id'], []).append(rid)
    rb = c.get('replaced_by')
    if rb: replaced_by_map[c['id']] = rb
print('replaces edges:', replaces_map)
print('replaced_by edges:', replaced_by_map)
violations = []
for a, bs in replaces_map.items():
    for b in bs:
        bc = id2can.get(b)
        if bc is None:
            violations.append(a + '.replaces -' + ' ' + b + ' (target not in set)')
            continue
        if bc.get('replaced_by') != a:
            violations.append(a + '.replaces -' + ' ' + b + ' but ' + b + '.replaced_by=' + repr(bc.get('replaced_by')))
        if bc.get('status') != 'superseded':
            violations.append(a + '.replaces -' + ' ' + b + ' but ' + b + '.status=' + repr(bc.get('status')))
for b, a in replaced_by_map.items():
    ac = id2can.get(a)
    if ac is None:
        violations.append(b + '.replaced_by -' + ' ' + a + ' (target not in set)')
        continue
    if b not in (ac.get('replaces') or []):
        violations.append(b + '.replaced_by=' + a + ' but ' + a + '.replaces=' + repr(ac.get('replaces')))
print('supersession invariant violations:', violations if violations else 'NONE')
