can_by_id = {c['id']: c for c in can}
problems = []
for cid, c in can_by_id.items():
    r = raw_by_id.get(cid)
    raw_refs = set(s.get('ref') for s in (r.get('sources') or []))
    can_refs = set(s.get('ref') for s in (c.get('sources') or []))
    if not (can_refs & raw_refs):
        problems.append(cid)
print('objects whose canonical sources share no ref with raw:', problems if problems else 'NONE')
# every canonical source ref should point to a real file in the repo (or the absolute parity path exists outside)
import os
missing_files = []
for cid, c in can_by_id.items():
    for s in (c.get('sources') or []):
        ref = s.get('ref') or ''
        if ref.startswith('/'):
            if not os.path.exists(ref):
                missing_files.append((cid, ref))
        else:
            if not os.path.exists(ref):
                missing_files.append((cid, ref))
print('canonical source refs pointing to missing files:', missing_files if missing_files else 'NONE')
# also confirm decided_by/status/content alignment raw vs canonical for a sample
for cid in ['D01', 'D14', 'D15']:
    r = raw_by_id[cid]; c = can_by_id[cid]
    same = (r['statement'] == c['statement'] and r['status'] == c['status'] and r['decided_on'] == c['decided_on'])
    print(cid, 'statement/status/decided_on identical raw-vs-canonical:', same)
